11	    static Graph fromAdjacencyMatrix(int[][] adjacencyMatrix) {
12	        validateAdjacencyMatrix(adjacencyMatrix);
13	        return new NeighborListGraph(buildNeighbors(adjacencyMatrix));
14	    }
