16	    private static void validateAdjacencyMatrix(int[][] adjacencyMatrix) {
17	        if (adjacencyMatrix == null || adjacencyMatrix.length == 0) {
18	            throw new IllegalArgumentException("Graph must contain at least one vertex.");
19	        }
20	
21	        for (int row = 0; row < adjacencyMatrix.length; row++) {
22	            if (adjacencyMatrix[row] == null || adjacencyMatrix[row].length != adjacencyMatrix.length) {
23	                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
24	            }
25	        }
26	
27	        for (int row = 0; row < adjacencyMatrix.length; row++) {
28	            if (adjacencyMatrix[row][row] != NO_EDGE) {
29	                throw new IllegalArgumentException("Graph diagonal must be zero.");
30	            }
31	
32	            for (int column = row + 1; column < adjacencyMatrix.length; column++) {
33	                if (adjacencyMatrix[row][column] != adjacencyMatrix[column][row]) {
34	                    throw new IllegalArgumentException("Graph must be undirected and symmetric.");
35	                }
36	            }
37	        }
38	    }
