40	    private static List<List<Neighbor>> buildNeighbors(int[][] adjacencyMatrix) {
41	        List<List<Neighbor>> neighborsByVertex = new ArrayList<>(adjacencyMatrix.length);
42	
43	        for (int row = 0; row < adjacencyMatrix.length; row++) {
44	            int[] copiedRow = Arrays.copyOf(adjacencyMatrix[row], adjacencyMatrix[row].length);
45	            List<Neighbor> neighbors = new ArrayList<>();
46	
47	            for (int column = 0; column < copiedRow.length; column++) {
48	                int edgeWeight = copiedRow[column];
49	                if (edgeWeight != NO_EDGE) {
50	                    neighbors.add(new Neighbor(column, edgeWeight));
51	                }
52	            }
53	
54	            neighborsByVertex.add(List.copyOf(neighbors));
55	        }
56	
57	        return List.copyOf(neighborsByVertex);
58	    }
59	}

